#!/usr/bin/env python3
# coding: utf-8
"""Additive, source-backed MIRA launch pages. No customer data or external requests."""
from pathlib import Path
import csv,html,hashlib,json,re,importlib.util
ROOT=Path(__file__).resolve().parents[1]
E=html.escape

def write(path,text):
    p=ROOT/path;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(text,'utf-8')

def shell(title,body,theme='direct',script=True):
    return f'''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta name="referrer" content="no-referrer"><meta http-equiv="Content-Security-Policy" content="default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self'; connect-src 'self'; object-src 'none'; base-uri 'none'; form-action 'none'"><title>{E(title)} — МИРА</title><meta name="description" content="Зарубежное направление для агентства. Ваш клиент, ваш бренд. Каталог Пхукета, документы и подготовка к первому запросу."><link rel="stylesheet" href="/mira/launch/launch.css">{'<script type="module" src="/mira/launch/launch.mjs"></script>' if script else ''}</head><body class="{theme}"><a class="skip" href="#main">К содержанию</a><header class="wrap nav"><a class="wordmark" href="/mira/start/">МИРА<i>↗</i></a><nav class="nav-links" aria-label="Навигация"><a href="/mira/phuket/">Каталог Пхукета</a><a href="/mira/documents/">Документы</a><a class="login" href="/mira/access/">Подключение</a></nav></header><main id="main">{body}</main><footer class="wrap footer"><a class="wordmark" href="/mira/start/">МИРА↗</a><a href="/mira/phuket/">Каталог</a><a href="/mira/documents/">Договор и документы</a><a href="/mira/variants/">Варианты дизайна</a><a href="/mira/marketplace-design.html">Демо кабинета</a><p>МИРА / WEST EAST TRADE GROUP PTE. LTD. · Публичный каталог — исходная база для знакомства, не подтверждённое наличие. Условия проекта и договор согласуются отдельно. Публичный приём заявок агентств открыт.</p></footer></body></html>'''

def door():
    return '''<div class="door-scene" aria-label="Открытая дверь в новое направление"><div class="door-view"><img src="/images/hero/hero-phuket-infinity-pool-m.jpg" width="900" height="1100" alt="Атмосферная иллюстрация зарубежной недвижимости, не конкретное предложение" fetchpriority="high"></div><div class="door-leaf" aria-hidden="true"></div><span class="mini-mark" aria-hidden="true">↗</span><div class="destination-tag">Пхукет — в вашем агентстве<small>Ваш клиент. Ваш бренд.</small></div><span class="scene-note">Атмосферная иллюстрация · права для рекламы требуют согласования</span></div>'''

def console():
    return '''<div class="proof-console"><div class="console-top"><b>МИРА / Рабочая модель</b><span>01 — Пхукет</span></div><p class="console-title">Не новый офис.<br>Новое направление.</p><div class="console-grid"><a href="/mira/phuket/"><b>Проекты</b>Открыть исходный каталог ↗</a><a href="/mira/documents/"><b>Условия</b>Изучить договор ↗</a><a href="/mira/marketplace-design.html?view=clients"><b>Статусы</b>Посмотреть в демо ↗</a><a href="/mira/marketplace-design.html?view=onboarding"><b>Команда</b>Порядок onboarding ↗</a></div><p class="console-note">Это схема продукта, не реальные данные агентства. Коммерческий доступ — после согласования проекта и подключения защищённого кабинета.</p></div>'''

def qualifier():
    return '''<section class="section wrap" id="start"><div class="qualify"><div><p class="eyebrow">Начнём с вашей задачи</p><h2>Какой первый шаг<br>подходит вам?</h2><p>Оставьте рабочий контакт и задачу агентства. Команда МИРА получит заявку и ответит в вашей квитанции.</p><p class="fine">Приглашение не требуется. Данные покупателей не нужны. Форма справа помогает составить личный план; он остаётся в этой вкладке.</p><a class="button" href="https://pilot.wegc.fund/mira/request/">Подать заявку агентства ↗</a></div><div class="form-body"><form id="brief-form"><fieldset disabled><legend>Ваше агентство</legend><label>Зарубежное направление<select name="experience"><option value="new">Пока работаем на домашнем рынке</option><option value="existing">Уже продаём зарубежные объекты</option><option value="thailand">Уже работаем с Таиландом</option></select></label><label>Задача сейчас<select name="demand"><option value="learning">Понять модель и возможности</option><option value="current">Разобрать конкретный запрос</option><option value="team">Подготовить команду</option></select></label><label>Интересующий рынок<select name="market"><option value="phuket">Пхукет</option><option value="bali">Бали — пока сбор интереса</option></select></label><button class="button" type="submit">Получить план знакомства ↗</button></fieldset></form><div id="brief-result" class="plan" hidden tabindex="-1" role="status"><h3>Ваш следующий шаг</h3><p></p><a href="/mira/phuket/">Открыть каталог Пхукета ↗</a><a href="/mira/documents/agency-agreement.html">Прочитать проект договора ↗</a><button class="button secondary" id="download-brief" type="button">Скачать локальный бриф ↓</button></div><noscript><p>Для плана включите JavaScript. Каталог и документы доступны по ссылкам.</p></noscript></div></div></section>'''

def common(count,variant):
    headline={'direct':'Два шага к новому направлению.','growth':'Не переезжайте.<br>Расширяйте ассортимент.','business':'Подключение под задачу<br>вашего агентства.'}[variant]
    return f'''<div class="wrap promise-bar"><span>Клиент остаётся с вами</span><span>Ваш бренд и ваша CRM</span><span>Комиссия — по договору проекта</span></div><section class="section wrap" id="how"><div class="section-head"><div><p class="eyebrow">Без нового офиса за границей</p><h2>{headline}</h2></div><p>Сначала знакомство с предложением и моделью. Затем — согласованный проект и подготовка первого клиентского запроса.</p></div><div class="steps"><article class="step"><b>01</b><h3>Посмотрите проекты.<br>Изучите условия.</h3><p>Каталог Пхукета и проект договора открыты. Выберите направление разговора, не меняя привычный процесс работы агентства.</p><a href="/mira/phuket/">Открыть каталог ↗</a></article><article class="step"><b>02</b><h3>Согласуйте проект.<br>Подключите команду.</h3><p>До реального запроса отдельно подтверждаем предложение, порядок регистрации, материалы и комиссию. Оставьте заявку агентства без приглашения; условия сотрудничества согласуем после рассмотрения.</p><a href="https://pilot.wegc.fund/mira/request/">Подать заявку агентства ↗</a></article></div><p class="fine">Два шага описывают путь подключения, а не гарантируют продажу, одобрение застройщика или открытый доступ за два клика.</p></section><section class="section wrap"><p class="eyebrow">Вы ведёте клиента. Мы дополняем вашу работу.</p><h2>Зарубежный запрос —<br>не повод отдавать клиента.</h2><div class="role-grid"><article><span class="label">На вашей стороне</span><h3>Клиент. Бренд. Отношения.</h3><p>Ваш менеджер продолжает общение.</p><p>Клиентская база остаётся в вашей CRM.</p><p>Вы определяете следующий шаг с покупателем.</p></article><article><span class="label">На стороне МИРА</span><h3>Проект. Документы. Координация.</h3><p>Подготовка предложения и разрешённых материалов.</p><p>Взаимодействие по правилам застройщика.</p><p>Документированный порядок статусов и комиссии.</p></article></div><p class="fine">Сохранение отношений с клиентом — принцип МИРА. Принятие регистрации и срок защиты определяет застройщик по конкретному проекту.</p><div class="catalogue-strip"><div><p class="eyebrow">Первый рынок — Пхукет</p><span class="number">{count}</span><h3>проектных записей<br>для знакомства с рынком</h3><a class="text-link" href="/mira/phuket/">Открыть полный каталог ↗</a><p class="fine">Число записей исходной базы, не подтверждённый остаток объектов. Бали — следующий интерес, не действующий ассортимент.</p></div><div class="property-preview"><figure><img src="/images/title-vivi-exterior-3.webp" loading="lazy" width="640" height="400" alt="Архивная визуализация The Title Vivi"><figcaption>The Title Vivi<small>Архивная визуализация · не наличие</small></figcaption></figure><figure><img src="/images/the-modeva-exterior-4-1.webp" loading="lazy" width="640" height="400" alt="Архивная визуализация The Modeva"><figcaption>The Modeva<small>Архивная визуализация · не наличие</small></figcaption></figure></div></div></section><section class="section wrap faq"><p class="eyebrow">Вопросы, которые задаёт руководитель</p><h2>По делу, до подключения.</h2><details><summary>Я должен передать вам своего клиента?</summary><p>Нет, модель МИРА строится вокруг сохранения ваших отношений с клиентом. Передача необходимых данных для конкретной регистрации — отдельная согласованная процедура, а не продажа клиентской базы.</p></details><details><summary>Сколько комиссии получает агентство?</summary><p>Размер, база расчёта и момент выплаты согласуются письменно по проекту. Универсального процента для всех объектов нет. Условия можно изучить до работы; платёжная поддержка покупателя не смешивается с агентской комиссией.</p></details><details><summary>Можно уже продавать все проекты из каталога?</summary><p>Нет. Открытая база нужна для поиска и знакомства. До предложения клиенту подтверждаются наличие, продавец, право работать через агентство, материалы, регистрация и коммерческий график.</p></details><details><summary>У нас уже есть зарубежный отдел. Зачем МИРА?</summary><p>Начните не с замены отдела, а с конкретной задачи: дополнительный проект, материалы или координация регистрации. Команда, CRM и отношения с клиентами остаются вашими.</p></details><details><summary>Где договор и что с рабочим входом?</summary><p><a href="/mira/documents/">Полный пакет документов открыт для чтения.</a> Он имеет статус проекта до согласования. <a href="/mira/access/">Приём заявок агентств — по приглашению</a>; локальный план и демо не изображают настоящую регистрацию.</p></details></section>'''+qualifier()+'''<a class="button sticky-action" href="#start" hidden>Подготовить подключение ↗</a>'''

def build():
    reg=ROOT/'project-bible/mira/data/phuket-project-master.csv'
    rows=list(csv.DictReader(reg.open(encoding='utf-8-sig')))
    spec=importlib.util.spec_from_file_location('source',ROOT/'scripts/mira-launch-source.py');mod=importlib.util.module_from_spec(spec);spec.loader.exec_module(mod)
    raw=(ROOT/'ru/wegc-catalog-data.js').read_bytes();original=mod.read_catalog(raw.decode())
    if len(rows)!=len(original) or {r['source_slug']for r in rows}!={r['slug']for r in original}:raise ValueError('Phuket coverage mismatch')
    media={'title-vivi':'/images/title-vivi-exterior-3.webp','the-title-artrio':'/images/the-title-artrio-exterior-4-1.webp','the-modeva':'/images/the-modeva-exterior-4-1.webp','the-title-katabello':'/images/the-title-katabello-exterior-2.webp','the-title-adora':'/images/the-title-adora-exterior-9.webp'}
    records=[]
    for r in rows:
        if not re.fullmatch(r'[a-z0-9]+(?:-[a-z0-9]+)*',r['source_slug']):raise ValueError('unsafe slug')
        records.append({'id':r['project_id'],'slug':r['source_slug'],'name':r['project_name'],'district':r['district_raw'],'kind':r['property_type_raw'],'family':r['developer_family']if r['developer_family']!='unknown'else'','basis':r['mapping_basis'],'image':media.get(r['source_slug']),'sourceRow':int(r['source_row']),'verifiedAt':None,'registrationEnabled':False})
    count=len(records)
    write('mira/data/phuket.json',json.dumps({'version':1,'scope':'research','count':count,'source':'ru/wegc-catalog-data.js','sourceSha256':hashlib.sha256(raw).hexdigest(),'records':records},ensure_ascii=False,separators=(',',':'))+'\n')
    heroes={
    'direct':'''<div class="wrap"><section class="hero"><div class="hero-grid"><div><p class="eyebrow">Для агентств недвижимости</p><h1>Ваш клиент<br>хочет Пхукет?<br><span>Не отпускайте<br>его к другим.</span></h1><p class="lead">Добавьте зарубежное направление в своё агентство. МИРА помогает с проектом и международной частью сделки. Вы остаётесь рядом с клиентом.</p><div class="actions"><a class="button" href="/mira/phuket/">Открыть каталог ↗</a><a class="text-link" href="https://pilot.wegc.fund/mira/request/">Подать заявку агентства ↗</a></div><p class="fine">Каталог открыт без регистрации. Рабочее подключение и условия проекта согласуются отдельно.</p><button id="motion-toggle" class="motion-control" hidden type="button">Остановить движение</button></div>'''+door()+'''</div></section></div>''',
    'growth':'''<section class="hero wrap"><div class="hero-grid"><p class="eyebrow">Новое направление. Знакомая работа.</p><h1>Вы продаёте квартиры.<br>А можете — <span>ещё и Пхукет.</span></h1><p class="lead">Не открывайте офис в Таиланде. Начните со запроса своего клиента — под своим брендом и с международной поддержкой МИРА.</p><div class="actions"><a class="button" href="https://pilot.wegc.fund/mira/request/">Подать заявку агентства ↗</a><a class="text-link" href="/mira/phuket/">Сначала посмотреть проекты</a></div><p class="fine">Доступ к рабочим проектам — после договора и согласования. Каталог не заменяет проверку наличия.</p><button id="motion-toggle" class="motion-control" hidden type="button">Остановить движение</button><div class="chat-row" aria-label="Иллюстрация клиентского запроса, не отзыв"><div class="chat-bubble"><small>ПРИМЕР ВОПРОСА ПОКУПАТЕЛЯ</small>«А за границей что-нибудь<br>смотрим?»</div><span class="chat-arrow" aria-hidden="true">→</span><div class="chat-bubble answer"><small>НОВОЕ НАПРАВЛЕНИЕ В ВАШЕМ АГЕНТСТВЕ</small>Теперь этот разговор<br>не обязательно отдавать.</div></div></div></section>''',
    'business':'''<section class="hero wrap"><div class="hero-grid"><div><span class="label">МИРА ДЛЯ АГЕНТСТВ</span><h1>Зарубежное<br>направление.<br><span>Внутри вашего<br>бизнеса.</span></h1><p class="lead">Расширяйте предложение агентства без отдельной международной инфраструктуры. Сохраняйте свой бренд, команду и отношения с покупателем.</p><div class="actions"><a class="button" href="https://pilot.wegc.fund/mira/request/">Подать заявку агентства ↗</a><a class="text-link" href="/mira/documents/">Изучить условия</a></div><p class="fine">Первый рынок — Пхукет. Коммерческий допуск каждого проекта проверяется отдельно.</p><button id="motion-toggle" class="motion-control" hidden type="button">Остановить движение</button></div>'''+console()+'''</div></section>'''}
    for theme,route,title in [('direct','start','Пхукет в вашем агентстве'),('growth','growth','Новое направление. Ваша команда'),('business','business','Международное направление для агентства')]:
        write(f'mira/{route}/index.html',shell(title,heroes[theme]+common(count,theme),theme))
    cards=''
    for n,route,title,desc in [('01','start','Не отпускайте<br>зарубежный запрос.','Прямой оффер, контраст, открытая дверь. Для холодного трафика и выставочного QR.'),('02','growth','Вы продаёте квартиры.<br>А можете — ещё и Пхукет.','Разговорная подача для региональной команды. Без ощущения банковской или luxury-презентации.'),('03','business','Новый рынок.<br>Ваш бизнес.','Сдержанная корпоративная подача. Для руководителей, сетей и действующего зарубежного отдела.')]:
        cards+=f'<article class="variant-card"><div class="variant-face"><span>ВАРИАНТ {n}</span><b>{title}</b><span>МИРА ↗</span></div><div class="variant-info"><p>{desc}</p><a href="/mira/{route}/">Открыть вариант ↗</a></div></article>'
    write('mira/variants/index.html',shell('Три подачи для агентства',f'<section class="section wrap"><p class="eyebrow">ВЫБОР ВЛАДЕЛЬЦА / НЕ АВТОМАТИЧЕСКОЕ УТВЕРЖДЕНИЕ</p><h2>Одна МИРА.<br>Три разных первых впечатления.</h2><div class="variant-cards">{cards}</div><div class="actions"><a href="/mira/design/">Сохранённый редакционный вариант ↗</a><a href="/mira/agency/">Сохранённая исходная воронка ↗</a><a href="/mira/expo/">Выставочный баннер ↗</a></div><p class="fine">Все варианты используют один каталог и один комплект документов. Публичные страницы не включают рабочую регистрацию и не меняют коммерческие условия.</p></section>',script=False))
    access='''<section class="section wrap"><div class="access-box"><span class="status">Публичный приём заявок открыт</span><h1>Начните работу<br>с МИРА.</h1><p>Расскажите о своём агентстве и задаче. Приглашение не требуется: запрос поступит команде МИРА, а вы получите личную квитанцию со статусом и ответом.</p><ol class="intake-steps"><li><strong>Отправьте заявку.</strong> Укажите агентство, рабочий контакт и задачу. Данные покупателей не нужны.</li><li><strong>Сохраните квитанцию.</strong> Не закрывайте вкладку до получения ответа. Номер подтверждает, что запрос сохранён.</li><li><strong>Обсудите следующий шаг.</strong> Оператор ответит в квитанции. Договор, проекты и коммерческие условия согласуем отдельно.</li></ol><div class="actions"><a class="button" href="https://pilot.wegc.fund/mira/request/">Подать заявку агентства ↗</a><a class="button secondary" href="/mira/catalog/">Посмотреть проекты ↗</a></div><p class="fine">Уже получили приглашение в рабочий кабинет? <a href="https://pilot.wegc.fund/mira/pilot.html">Войти по приглашению</a>.</p><div class="actions"><a href="/mira/documents/agency-agreement.html">Проект договора</a><a href="https://pilot.wegc.fund/mira/request/privacy">Как обрабатываются данные заявки</a></div></div></section>'''
    write('mira/access/index.html',shell('Подключение агентства',access,script=False))
    write('mira/expo/index.html',shell('Выставочный баннер', '''<section class="section wrap"><p class="eyebrow">МАКЕТ ДЛЯ СОГЛАСОВАНИЯ / 25 СЕНТЯБРЯ — КОНТЕКСТ ВЛАДЕЛЬЦА</p><h2>Пхукет —<br>в вашем агентстве.</h2><p>QR ведёт на постоянный адрес новой прямой воронки. Макет не содержит вымышленных комиссий, гарантий дохода и чужих логотипов.</p><img class="expo-preview" src="banner.svg" width="850" height="2000" alt="Баннер МИРА: Пхукет в вашем агентстве, QR на лендинг"><div class="actions"><a class="button" href="banner.pdf">Скачать векторный PDF ↓</a><a href="banner.svg">Открыть SVG ↗</a><a href="qr.svg">Отдельный QR ↗</a><a href="/mira/start/">Проверить страницу QR ↗</a></div><p class="fine">Рабочая пропорция 85×200 см — предложение дизайна, не подтверждённый размер стенда. Перед печатью нужны согласование владельца, требования типографии, цветовой профиль и проба QR на физическом носителе.</p></section>''',script=False))
    write('mira/launch/release.json',json.dumps({'version':'cp13','source_records':count,'legal_documents':9,'live_registration_enabled':False,'owner_design_approved':False,'funnel_routes':['/mira/start/','/mira/growth/','/mira/business/'],'preserved_routes':['/mira/design/','/mira/agency/','/mira/marketplace-design.html']},ensure_ascii=False,indent=2))
    print(json.dumps({'records':count,'variants':3,'registration_enabled':False}))

if __name__=='__main__':build()

# Complete, no-JavaScript-readable project detail layer from the same source set.
def build_catalogue():
    data=json.loads((ROOT/'mira/data/phuket.json').read_text());rows=data['records'];kinds={'condo':'Кондоминиум','villa':'Вилла'}
    top=f'''<section class="catalogue-head"><div><p class="eyebrow">ТАИЛАНД / КАТАЛОГ ДЛЯ АГЕНТСТВ</p><h1>Пхукет.<br><span>Ваш следующий рынок.</span></h1><p>Найдите проект. Соберите подборку. Начните разговор о новом направлении — под брендом своего агентства.</p></div><aside class="catalogue-total"><b id="total">{len(rows)}</b><span>проектных записей<br>в исходной базе</span></aside></section>'''
    notice='''<details class="catalogue-notice"><summary>Исследовательский каталог, а не подтверждённое наличие</summary><p>Районы, типы и группы перенесены из существующего источника и требуют проверки. Здесь нет автоматически рассчитанных цен или обещанной комиссии. Наличие единицы, продавец, материалы и регистрационные правила подтверждаются перед реальным предложением.</p></details>'''
    body=top+notice+'''<section id="catalogue"><div class="catalogue-tools"><label>Название, район или группа<input id="q" type="search" maxlength="200" autocomplete="off" placeholder="Например, The Title или Банг Тао" disabled></label><details id="filter-options" open><summary>Район и тип по исходной базе</summary><div class="filter-row"><label>Район<select id="district" disabled><option value="">Все районы</option></select></label><label>Тип<select id="kind" disabled><option value="">Все типы</option><option value="condo">Кондоминиумы</option><option value="villa">Виллы</option></select></label><button id="reset" disabled>Сбросить фильтры</button></div></details></div><div class="catalogue-controls"><p id="count" role="status">Загружаем каталог…</p><div><button id="saved" aria-pressed="false" disabled>Подборка (0)</button><button id="download-selection" disabled>Скачать бриф ↓</button></div></div><div id="catalog-error" class="error-panel" hidden role="alert"><h2>Каталог не загрузился</h2><p>Ошибочные или неполные данные не подставляются вместо исходной базы.</p><button id="retry">Повторить загрузку</button></div><div id="empty" class="error-panel" hidden><h2>В этой выборке пока пусто</h2><button id="empty-reset">Показать все проекты</button></div><div id="cards" class="cards"></div><nav class="pagination" aria-label="Страницы"><button id="prev" disabled>← Назад</button><span id="page-count">—</span><button id="next" disabled>Дальше →</button></nav><p class="fine">Подборка остаётся только в текущей вкладке. Скачивание брифа не отправляет запрос МИРА и не регистрирует клиента.</p><noscript><div class="noscript-catalogue">Для поиска нужен JavaScript. <a href="pages/1/">Все проекты доступны также постранично без JavaScript.</a></div></noscript></section><section class="section"><h2>Сначала проект.<br>Затем — подтверждённые условия.</h2><div class="actions"><a class="button" href="/mira/access/">Подготовка подключения ↗</a><a href="/mira/documents/agency-agreement.html">Прочитать договор ↗</a></div></section>'''
    dialog='''<dialog id="detail" aria-labelledby="project-title"><div class="dialog-nav"><span>КАРТОЧКА ИСХОДНОЙ ЗАПИСИ</span><button id="close-detail" aria-label="Закрыть карточку">Закрыть ×</button></div><div id="detail-content"></div></dialog>'''
    text=shell('Полный каталог Пхукета','<div class="wrap">'+body+'</div>'+dialog,script=False).replace('</head>','<link rel="stylesheet" href="/mira/phuket/catalogue.css"><script type="module" src="/mira/phuket/catalogue.mjs"></script></head>')
    write('mira/phuket/index.html',text)
    for r in rows:
        fields=[('Район по источнику',r['district']),('Тип по источнику',kinds.get(r['kind'],r['kind'])),('Группа / бренд, не продавец',(r['family']or'Не установлена')+(' — кандидат из базы' if r['basis']!='existing_seed_mapping' and r['family']else'')),('Актуальные цена и наличие','Не подтверждены'),('Комиссия и регистрация','Согласуются отдельно по проекту'),('Происхождение',f"{data['source']} · строка {r['sourceRow']} · {r['id']}")]
        content='<section class="section wrap project-static"><a href="/mira/phuket/">← Полный каталог</a><p class="eyebrow">ПХУКЕТ / ИСХОДНАЯ КАРТОЧКА</p><h1>'+E(r['name'])+'</h1>'
        if r['image']:content+=f'<img src="{r["image"]}" width="1280" height="800" alt="Архивная визуализация {E(r["name"])}"><p class="fine">Архивная визуализация, не текущее состояние и не наличие.</p>'
        content+='<dl class="detail-facts">'+''.join('<div><dt>'+E(k)+'</dt><dd>'+E(v)+'</dd></div>'for k,v in fields)+'</dl><p>Эта запись показывает происхождение сведений, а не подтверждает готовность проекта к продаже через МИРА. Юридический продавец, наличие, полномочия, материалы и правила клиента проверяются отдельно.</p><div class="actions"><a class="button" href="/mira/access/">Подготовить подключение ↗</a><a href="/mira/documents/project-rules.html">Порядок проверки проекта ↗</a></div></section>'
        text=shell(r['name'],content,script=False).replace('</head>','<link rel="stylesheet" href="/mira/phuket/catalogue.css"></head>')
        write(f'mira/phuket/project/{r["slug"]}/index.html',text)
    pages=(len(rows)+23)//24
    for page in range(1,pages+1):
        part=rows[(page-1)*24:page*24]
        links=''.join(f'<p><a href="/mira/phuket/project/{r["slug"]}/">{E(r["name"])}</a> — {E(r["district"])}</p>'for r in part)
        nav='<nav class="page-list">'+''.join(f'<a href="/mira/phuket/pages/{i}/"'+(' aria-current="page"'if page==i else'')+f'>{i}</a>'for i in range(1,pages+1))+'</nav>'
        write(f'mira/phuket/pages/{page}/index.html',shell(f'Пхукет — страница {page}',f'<section class="section wrap"><a href="/mira/phuket/">← Поиск и фильтры</a><h2>Исходный каталог / {page} из {pages}</h2>{notice}{links}{nav}</section>',script=False).replace('</head>','<link rel="stylesheet" href="/mira/phuket/catalogue.css"></head>'))

if __name__=='__main__':build_catalogue()
